/*
 * Card artwork, exported from Figma (file dJlTbm29dlfvDuTQa6DfAQ, page Process).
 *
 * Inlined rather than imported: the project has no SVG transformer for Metro,
 * and adding one to load a handful of fixed files is more moving parts than it
 * buys. Root width/height are left exactly as exported — scale these by passing
 * proportional width/height to SvgXml, never by rewriting the markup.
 */

/** Whose mark goes on the card. */
export type SignatureKey = 'ilya' | 'borya' | 'taras';

export const SIGNATURE_KEYS: SignatureKey[] = ['ilya', 'borya', 'taras'];

export const SIGNATURE_LABELS: Record<SignatureKey, string> = {
  ilya: 'Илья',
  borya: 'Боря',
  taras: 'Тарас',
};

/**
 * Where a mark sits on the 900 x 570 design, and how it is turned.
 *
 * `box` is the frame Figma reserves for it — often much larger than the card,
 * because these run off the edges. `art` is the vector's own size, centred in
 * that box. Figma exports the vector untransformed, so the rotation and the
 * mirror have to be re-applied here or every one of them lands upside down.
 */
export type ArtPlacement = {
  box: { left: number; top: number; width: number; height: number };
  art: { width: number; height: number };
  rotate: number;
  flipX: boolean;
};

export const SIGNATURE_PLACEMENT: Record<SignatureKey, ArtPlacement> = {
  // inset -54.04% / -50.63% / -51.03% / 16.67%
  ilya: {
    box: { left: 150.03, top: -308.03, width: 1205.634, height: 1168.865 },
    art: { width: 1205.634, height: 1168.865 },
    rotate: 180,
    flipX: true,
  },
  // inset -1.58% / -7.69% / -22.88% / 6.67%, vector turned 150°
  borya: {
    box: { left: 60.03, top: -9.01, width: 909.187, height: 709.432 },
    art: { width: 865.325, height: 319.586 },
    rotate: 150,
    flipX: true,
  },
  // inset 8.25% / -5.81% / 6.46% / 16.56%
  taras: {
    box: { left: 149.04, top: 47.03, width: 803.282, height: 486.205 },
    art: { width: 803.282, height: 486.205 },
    rotate: 180,
    flipX: true,
  },
};

/**
 * Measured off the exported design rather than guessed: on every variant the
 * white stroke's core sits at exactly G=128 over #FF0042 — half opacity — while
 * the red stroke on the paper face is a flat #FF0042.
 */
export const SIGNATURE_FRONT_OPACITY = 0.5;
export const SIGNATURE_BACK_OPACITY = 1;

/** The barcode is exported mirrored vertically; undo it at the call site. */
export const BARCODE_FLIP = { transform: [{ scaleY: -1 }] } as const;

